import type { BrandAvatarItemProps } from 'components/BrandAvatar/Components/BrandAvatarItem/interface';

import type { BeerEvolutionBreakdownData } from '../../../../types';
import { isBeerEvolutionBreakdownDataAligned } from './beerEvolutionDataValidation';

export const resolveBeerEvolutionTestId = (
  dataTestId: string | undefined,
  suffix: string,
  fallback: string,
) => (dataTestId ? `${dataTestId}-${suffix}` : fallback);

export const mapWaterfallLabels = (
  chartLabels: BeerEvolutionBreakdownData['labels'],
) =>
  (chartLabels ?? []).map((label) => (Array.isArray(label) ? label[0] : label));

export const computeBeerEvolutionIsEmpty = (
  empty: boolean,
  data: BeerEvolutionBreakdownData | null | undefined,
  chartLabelsLength: number,
  chartValuesLength: number,
  hasAlignedChartData: boolean,
) =>
  empty ||
  data?.empty ||
  !data ||
  chartLabelsLength === 0 ||
  chartValuesLength === 0 ||
  !hasAlignedChartData;

export const hasAlignedBeerEvolutionChartData = (
  data: BeerEvolutionBreakdownData | null | undefined,
  chartLabelsLength: number,
  chartValuesLength: number,
) => {
  if (!data) {
    return false;
  }

  return isBeerEvolutionBreakdownDataAligned(
    data,
    chartLabelsLength,
    chartValuesLength,
  );
};

export const buildBeerEvolutionBrandAvatars = (
  data: BeerEvolutionBreakdownData | null | undefined,
  chartLabels: BeerEvolutionBreakdownData['labels'],
): BrandAvatarItemProps[] => {
  const labels = chartLabels ?? [];
  const images = data?.images?.data;

  if (!images?.length || images.length !== labels.length) {
    return [];
  }

  return images.map((brand, index) => {
    const labelEntry = labels[index];
    const country = Array.isArray(labelEntry) ? labelEntry[1] : undefined;

    return {
      ...brand,
      index,
      description: country ?? undefined,
      ...(brand.mainBrand?.src ? { mainBrand: brand.mainBrand } : {}),
    };
  });
};
